import{_ as s,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"4. C 程序剖析","description":"The Little Book of C 中文版 — 4. C 程序剖析","frontmatter":{"title":"4. C 程序剖析","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","01-入门","中文"],"description":"The Little Book of C 中文版 — 4. C 程序剖析","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":4,"sidebarWeight":4,"alternateZh":"/posts/c教程/zh-CN/01-入门/004-Anatomy of a C Program","alternateEn":"/posts/c教程/en-US/01-Getting Started/004-Anatomy of a C Program"},"headers":[],"relativePath":"posts/c教程/zh-CN/01-入门/004-Anatomy of a C Program.md","filePath":"posts/c教程/zh-CN/01-入门/004-Anatomy of a C Program.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/01-入门/004-Anatomy of a C Program.md"};function i(o,a,l,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/01-Getting Started/004-Anatomy of a C Program)</p><p>现在您的第一个程序已经运行，让我们打开它看看里面。每个 C 程序都遵循一个清晰的结构，一组规则告诉您和编译器每个部分的含义。尽早理解这种结构将帮助您充满信心地阅读、编写和调试代码。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>这是同一个程序，带有解释每个部分的注释：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span><span>      // 1. Preprocessor directive</span></span>
<span class="line"><span>// 2. Function definition</span></span>
<span class="line"><span>int main(void) {        // main: entry point of every C program</span></span>
<span class="line"><span>    printf(&quot;Hello, C!\\n&quot;);  // 3. Statement: prints a message</span></span>
<span class="line"><span>    return 0;           // 4. Return statement: signals success</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="四个主要部分" tabindex="-1">四个主要部分 <a class="header-anchor" href="#四个主要部分" aria-label="Permalink to &quot;四个主要部分&quot;">​</a></h4><p>预处理器指令以以下内容开头的行<code>#</code>在编译代码之前就已经处理了。它们包含或定义您的程序所依赖的事物。例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#define PI 3.14159</span></span></code></pre></div><p>函数 每个 C 程序都是由函数组成的。功能<code>main()</code>很特别，它是你的程序开始的地方。您可以定义更多函数来组织代码。</p><p>语句 函数内的每条指令都以分号结尾。这些是您的程序所采取的一一步骤。</p><p>注释 注释会被编译器忽略，但会被人类读取。用它们来解释你的代码为什么要做某事，而不仅仅是它做了什么。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// This is a single-line comment</span></span>
<span class="line"><span>/* This is a multi-line comment */</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>C是一种结构化语言。每个函数、语句和声明都存在于清晰的边界内。与脚本语言不同，没有自动设置或隐藏的运行时，您看到的一切都是运行的。</p><p>学习 C 程序的剖析会给你一个思维导图：</p><ul><li>你知道执行从哪里开始（<code>main</code>).</li><li>你知道代码所在的位置（函数内部）。</li><li>你知道库从哪里来（通过包含）。</li></ul><p>一旦这张图变得自然，阅读大型 C 程序就会开始变得轻松且合乎逻辑。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>创建文件<code>structure.c</code>包含以下内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void greet(void) {</span></span>
<span class="line"><span>    printf(&quot;Welcome to C programming!\\n&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    greet();</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc structure.c -o structure</span></span>
<span class="line"><span>./structure</span></span></code></pre></div><p>也许添加另一个功能<code>void bye(void)</code>打印一条再见消息，然后调用它<code>greet()</code>.</p><p>尝试删除<code>return 0;</code>，注意程序仍然如何运行，但添加它可以使您的意图清晰。</p><p>您编写的每个 C 程序都遵循这个基本形状。一旦你能够识别这些部分，你就可以开始构建更长、更智能、更接近系统的程序。</p>`,25)])])}const g=s(p,[["render",i]]);export{u as __pageData,g as default};
